import{_ as t,o as a,c as r,a5 as s}from"./chunks/framework.BwlBv862.js";const u=JSON.parse('{"title":"Current transports and platform restrictions","description":"","frontmatter":{"title":"Current transports and platform restrictions","docId":"developer.transports","translationKey":"developer.transports","locale":"en","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6696987a0db16b3b4d364c6136d0e552dbebd6fc68346e3ed031587a7b004468","translationRevision":"6696987a0db16b3b4d364c6136d0e552dbebd6fc68346e3ed031587a7b004468","order":200},"headers":[],"relativePath":"en/developer/transports.md","filePath":"en/developer/transports.md","lastUpdated":1794611623000}'),i={name:"en/developer/transports.md"};function o(n,e,d,l,c,p){return a(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="current-transports-and-platform-restrictions" tabindex="-1">Current transports and platform restrictions <a class="header-anchor" href="#current-transports-and-platform-restrictions" aria-label="Permalink to &quot;Current transports and platform restrictions {#current-transports-and-platform-restrictions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Select the transport that actually exists for the target build and platform. Read <a href="./control-api.html">Control API</a> and <a href="./collaboration.html">collaboration</a>. A transport carries serialized operations; it must not introduce a second core or grant authority by itself.</p><h2 id="choose-the-boundary" tabindex="-1">Choose the boundary <a class="header-anchor" href="#choose-the-boundary" aria-label="Permalink to &quot;Choose the boundary {#choose-the-boundary}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Current implementation</th><th>Important limit</th></tr></thead><tbody><tr><td>Desktop WebView</td><td>Wry IPC and shared control client</td><td>GUI/thread lifetime belongs to desktop</td></tr><tr><td>Local CLI</td><td>Unix socket or Windows named pipe; explicit stdio host</td><td>Same application home and owner</td></tr><tr><td>Local browser</td><td>Native loopback adapter plus <code>browser-transport.ts</code></td><td>Paired native host, not a mock or public remote server</td></tr><tr><td>Direct remote</td><td>Authenticated HTTPS/WSS gateway and SDK/browser transports</td><td>TLS, hello, grants and feature gates</td></tr><tr><td>Native peer</td><td><code>tiktools-peer</code>, encrypted iroh/QUIC stream</td><td>Peer identity is not RPC authority</td></tr><tr><td>Native WebRTC</td><td><code>tiktools-rtc</code>, signed signaling and data channels</td><td>Negotiation, grant and route checks remain required</td></tr></tbody></table><p>The TypeScript transport interface lives at <code>src/web/shared/api/control-transport.ts</code>. Native peer configuration does not implicitly enable public third-party relays or discovery. WebRTC is Rust-native (<code>webrtc</code> 0.21.1), not a dependency on browser <code>RTCPeerConnection</code> in the desktop UI.</p><h2 id="inspect-the-selected-route" tabindex="-1">Inspect the selected route <a class="header-anchor" href="#inspect-the-selected-route" aria-label="Permalink to &quot;Inspect the selected route {#inspect-the-selected-route}&quot;">​</a></h2><p>Discover the connected host&#39;s supported methods and capabilities before pairing or displaying a controller action:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> browser-transport</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote-browser-transport</span></span></code></pre></div><p><code>tiktools-rtc/src/route.rs</code> observes the selected ICE candidate pair to classify direct versus relay. Ready state alone cannot prove a direct route. Cloud signaling/relay plumbing is separate from business authorization and must retain native grant checks.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>Local IPC and desktop transport are established paths. Native peer, WebRTC and controller integration have source and focused tests, but deployment and multi-PC acceptance remain experimental. Legacy text claiming there is no peer/relay implementation is historical. Android local IPC works; persistent remote profiles have no selected credential store, and desktop native addons/WebViews remain unavailable there.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery {#recovery}&quot;">​</a></h2><p>Treat disconnect as possible uncertainty for accepted operations. Reconnect must invalidate private projections, renegotiate identity and resume or snapshot bounded streams. Never downgrade certificate checks or fall back silently to a local owner after remote failure. The <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-rtc/src" target="_blank" rel="noreferrer">RTC implementation</a> and actual feature graph supersede older transport plans.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Operational details {#operational-details}&quot;">​</a></h2><p>Peer uses ALPN <code>tiktools/collaboration/1</code>, a current 15 s connection timeout and at most four explicitly configured relays. Peer/RTC frames are capped at 1 MiB; RTC fragments into packets of at most 16 KiB. Oversized frames fail framing validation rather than becoming a partial RPC. Diagnose configuration/identity, signaling, connection timeout, frame size and authorization separately. Cloud relay is not an ICE TURN server; an empty relay list does not enable public discovery. Check host/device activity and current confirmed grant before testing a route, and record whether ICE selected direct or relay. A ready/encrypted transport proves neither RPC authority nor that every NAT is traversable. Test changed/revoked sessions and oversized frames with fixtures before real two-PC acceptance.</p>`,16)])])}const k=t(i,[["render",o]]);export{u as __pageData,k as default};
